    async clickStartRealPlay(oLiveView) {
      try {
        if (!this.f1Called) {
          await this.getWindows();
        }
        this.f1Called = false;
        // console.log(this.iWndIndex);
        await window.WebVideoCtrl.I_Stop({ iWndIndex: this.iWndIndex });
        var szDeviceIdentify = oLiveView.szIP + '_' + oLiveView.szPort;
        let startParams = {
          iStreamType: oLiveView.iStreamType,
          bZeroChannel: oLiveView.bZeroChannel,
          iWndIndex: this.iWndIndex,
          iPort:554,
        };
        if (oLiveView.iChannelID != null) {
          startParams.iChannelID = oLiveView.iChannelID;
        }

        await window.WebVideoCtrl.I_StartRealPlay(szDeviceIdentify, startParams, {
          success: (res) => {
            console.log(res);

          },
          error: (rek) => {
            console.log(rek);

          }
        });
        console.log('预览成功！');
        this.getMessage();
      } catch (status) {
        if (403 === status) {
          console.log('设备不支持Websocket取流！');
        } else {
          console.log('预览失败！');
          // this.$message({
          //   type: 'error',
