      window.WebVideoCtrl.I_ChangeWndNum(iType).then(() => {
        console.log("窗口分割成功！");
        this.textOpen=false
        // showOPInfo("窗口分割成功！");
      }, (oError) => {
        console.log("窗口分割失败！");
        this.textOpen=false
        console.log(oError);
        // var szInfo = "窗口分割失败！";
        // showOPInfo(szInfo, oError.errorCode, oError.errorMsg);
      });
    },
    async getWindows() {
      let num = this.selectedWndNum == 1 ? 1 : this.selectedWndNum == 2 ? 4 : this.selectedWndNum == 3 ? 9 : this.selectedWndNum == 4 ? 16 : 1
      let url = []
      for (let i = 0; i < num; i++) {
        let res = await window.WebVideoCtrl.I_GetWindowStatus(i)
        // console.log(res);
        if (res != null) {
          url.push(res)
        }
      }
      // this.urlArr = [...new Set(url)];
      // console.log(url);

      // 找出数组中已有的所有 iIndex 值
      let existingIndexes = url.map(item => item.iIndex);

      // 找到从 0 到 num 范围内第一个不在 existingIndexes 中的值
      let missingIndex = 0;
      while (existingIndexes.includes(missingIndex)) {
        missingIndex++;
      }

      // 将找到的空缺的最小值赋值给 iWndIndex
      this.iWndIndex = (missingIndex < num) ? missingIndex : 0;
      console.log("当前选中窗口为", this.iWndIndex)
    },
    async getMessage(oLiveView, type) {
      // 拿到当前窗口分割状况，并且计算出有几个窗口，获取所有窗口中的参数，拿到szIP，这些是已经登陆并且已经在播放的录像机，这里可以直接进行播放操作而不用进行登陆操作。
      let num = this.selectedWndNum == 1 ? 1 : this.selectedWndNum == 2 ? 4 : this.selectedWndNum == 3 ? 9 : this.selectedWndNum == 4 ? 16 : 1
      let url = []
      for (let i = 0; i < num; i++) {
        let res = await window.WebVideoCtrl.I_GetWindowStatus(i)
        // console.log(res);
        if (res != null) {
          url.push(res.szIP)
        }
      }
      this.urlArr = [...new Set(url)];
      // console.log(this.urlArr);

      // 检查当前点击的设备有没有登陆
      let res = this.urlArr.find(v => v == oLiveView.szIP);
      console.log("res======================", res);
      if (res == undefined) {//说明此时应该登陆
        if (type == 'real') {
          this.clickLogin(oLiveView)
        } else {
          this.clickLoginBack(oLiveView)
        }
      } else {
        if (type == 'real') {
          this.clickStartRealPlay(oLiveView)
        } else {
          this.clickStartPlayback(oLiveView)
        }
      }
    },
