    async clickStartPlayback(oLiveView) {
      console.log("回放参数检查", oLiveView);
      try {
        if (!this.f1Called) {
          await this.getWindows();
        }
        this.f1Called = false;
        await window.WebVideoCtrl.I_Stop({ iWndIndex: this.iWndIndex });
        var oWndInfo = window.WebVideoCtrl.I_GetWindowStatus(),
          szDeviceIdentify = oLiveView.szIP + '_' + oLiveView.szPort,
          iChannelID = oLiveView.iChannelID,
          bZeroChannel = oLiveView.bZeroChannel,
          iStreamType = oLiveView.iStreamType,
          szStartTime = oLiveView.szStartTime,
          szEndTime = oLiveView.szEndTime,
          iRtspPort = 8000,
          szInfo = "",
          bChecked = true,
          iRet = -1;

        if (null == szDeviceIdentify) {
          return;
        }

        if (bZeroChannel) {// 零通道不支持回放
          return;
        }
        if (bChecked) {// 启用转码回放
          // console.log("回放？？？？？");
          var oTransCodeParam = {
            TransFrameRate: "14",// 0：全帧率，5：1，6：2，7：4，8：6，9：8，10：10，11：12，12：16，14：15，15：18，13：20，16：22
            TransResolution: "1",// 255：Auto，3：4CIF，2：QCIF，1：CIF
            TransBitrate: "19"// 2：32K，3：48K，4：64K，5：80K，6：96K，7：128K，8：160K，9：192K，10：224K，11：256K，12：320K，13：384K，14：448K，15：512K，16：640K，17：768K，18：896K，19：1024K，20：1280K，21：1536K，22：1792K，23：2048K，24：3072K，25：4096K，26：8192K
          };
          window.WebVideoCtrl.I_StartPlayback(szDeviceIdentify, {
            // iRtspPort: iRtspPort,
            iStreamType: iStreamType,
            iChannelID: iChannelID,
            szStartTime: szStartTime,
            szEndTime: szEndTime,
            iWndIndex: this.iWndIndex,
            oTransCodeParam: oTransCodeParam,
            success: function () {
              szInfo = "开始回放成功1！";
              console.log(szInfo);
              // showOPInfo(szDeviceIdentify + " " + szInfo);
            },
            error: function (oError) {
              szInfo = "开始回放失败！";
              console.log(szInfo, oError);
              // showOPInfo(szDeviceIdentify + szInfo, oError.errorCode, oError.errorMsg);
            }
          });
        } else {
          // console.log("走到这里来么02020202");
          console.log({
            'szDeviceIdentify': szDeviceIdentify,
            'iRtspPort': iRtspPort,
            'iStreamType': iStreamType,
            'iChannelID': iChannelID,
            'szStartTime': szStartTime,
            'szEndTime': szEndTime,
          });
          window.WebVideoCtrl.I_StartPlayback(szDeviceIdentify, {
            iRtspPort: iRtspPort,
            iStreamType: iStreamType,
            iChannelID: iChannelID,
            szStartTime: szStartTime,
            szEndTime: szEndTime,
