    async searchVideo(oLiveView) {
      const szDeviceIdentify = `${oLiveView.szIP}`;
      const iSearchPos = 0
      try {
        return await new Promise((resolve, reject) => {
          window.I_RecordSearch(szDeviceIdentify,
            oLiveView.iChannelID,
            oLiveView.szStartTime,
            oLiveView.szEndTime, {
            iStreamType: 1,
            iSearchPos: iSearchPos,
            success: (xml) => {
              const serializer = new XMLSerializer();
              const xmlString = serializer.serializeToString(xml); // 将 Document 转为字符串
              resolve(xmlString);
            },
            error: (err) => reject(err),
          });
        });
