<template>
  <div class="timeline" @click="handleClick">
    <div class="time-scale" ref="timeScale">
      <div v-for="(tick, index) in timeTicks" :key="index" class="tick">
        {{ tick }}
      </div>
    </div>
    <div class="current-time">{{ currentTime }}</div>
    <div class="progress-bar" :style="{ width: progressBarWidth }"></div>
  </div>
</template>

<script>
export default {
  props: {
    startTime: {
      type: String,
      required: true
    },
    endTime: {
      type: String,
      required: true
    },
    currentTimeExternal: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      timeTicks: [], // 存储时间刻度
      showCurrentTime: false, // 控制当前时间显示
      timelineWidth: 0, // 时间轴宽度
      progressBarWidth: '0%' // 进度条宽度
    };
  },
  mounted() {
    this.calculateTimeTicks();
    this.timelineWidth = this.$refs.timeScale.clientWidth;
  },
  computed: {
    currentTime() {
      return this.currentTimeExternal;
    }
  },
  watch: {
    currentTimeExternal(newVal) {
      this.updateProgressBar(newVal);
    }
  },
  methods: {
    calculateTimeTicks() {
      const start = new Date(this.startTime);
      const end = new Date(this.endTime);
      const diff = end.getTime() - start.getTime();
      const interval = diff / 10; // 将时间段分成10等份

      for (let i = 0; i <= 10; i++) {
        const tickTime = new Date(start.getTime() + i * interval);
        this.timeTicks.push(this.formatDate(tickTime));
      }
    },
    formatDate(date) {
      const year = date.getFullYear();
      const month = ('0' + (date.getMonth() + 1)).slice(-2);
      const day = ('0' + date.getDate()).slice(-2);
      const hours = ('0' + date.getHours()).slice(-2);
      const minutes = ('0' + date.getMinutes()).slice(-2);
      const seconds = ('0' + date.getSeconds()).slice(-2);
      return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
    },
    handleClick(event) {
      const offset = event.offsetX;
      const percent = offset / this.timelineWidth;
      const start = new Date(this.startTime).getTime();
      const end = new Date(this.endTime).getTime();
      const currentTime = new Date(start + percent * (end - start));
      this.$emit('time-selected', this.formatDate(currentTime));
    },
    updateProgressBar(currentTime) {
      const start = new Date(this.startTime).getTime();
      const end = new Date(this.endTime).getTime();
      const totalTime = end - start;
      const currentTimeMs = new Date(currentTime).getTime() - start;
      const percent = (currentTimeMs / totalTime) * 100;
      this.progressBarWidth = percent + '%';
      // console.log(this.progressBarWidth);
    }
  }
};
</script>

<style scoped>
.timeline {
  position: relative;
  width: 100%;
  height: 100%;
  border: 1px solid #ccc;
  cursor: pointer;
}
.time-scale {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 20px; /* 留出空间显示当前时间 */
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 10px;
}
.tick {
  flex: 1;
  text-align: center;
  white-space: nowrap;
}
.current-time {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  text-align: center;
  font-size: 12px;
  color: #fff;
  /* background-color: rgba(255, 255, 255, 0.8); */
  padding: 2px;
  z-index: 10;
}
.progress-bar {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 100%;
  background-color: #4caf50; /* 绿色 */
}
</style>